#include <stdio.h>
#define MAXN 500000

int x[MAXN];

long long count_leq(int limit, int n) {
    if (limit < 0) return 0;
    long long ans = 0;
    int left = 0;
    int sum = 0;
    for (int right = 0; right < n; ++right) {
        sum += x[right];
        while (sum > limit && left <= right) {
            sum -= x[left];
            ++left;
        }
        ans += (long long)(right - left + 1);
    }
    return ans;
}

int main() {
    int N, K;
    scanf("%d %d", &N, &K);
    for (int i = 0; i < N; ++i) {
        scanf("%d", &x[i]);
    }
    long long ans = count_leq(K, N) - count_leq(K - 1, N);
    printf("%lld\n", ans);
    return 0;
}
